def word_lengths(text, trace=False):
    """Return lengths of non-punctuation words after simple edge cleanup."""
    tokens = text.split()
    lengths = []
    for token in tokens:
        word = token.strip(".,!?")
        if word:
            lengths.append(len(word))
    if trace:
        print(f"tokens={tokens}")
        print(f"lengths={lengths}")
    return lengths


def average_word_length(text, trace=False):
    """Return 0.0 for no words; otherwise return the average word length."""
    lengths = word_lengths(text, trace=trace)
    if not lengths:
        return 0.0
    return round(sum(lengths) / len(lengths), 2)


