from html.parser import HTMLParser

HTML = '''
<main>
  <article data-rank="1"><h2>Reliable Robots</h2><span class="score">42</span></article>
  <article data-rank="2"><h2>Garden Sensors</h2><span class="score">35</span></article>
</main>
'''

class RankingParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.items = []
        self.current = None
        self.capture = None

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        if tag == "article":
            self.current = {"rank": int(attributes["data-rank"])}
        elif self.current is not None and tag == "h2":
            self.capture = "title"
        elif self.current is not None and tag == "span" and attributes.get("class") == "score":
            self.capture = "score"

    def handle_data(self, data):
        if self.current is not None and self.capture and data.strip():
            self.current[self.capture] = data.strip()

    def handle_endtag(self, tag):
        if tag in {"h2", "span"}:
            self.capture = None
        elif tag == "article" and self.current is not None:
            self.current["score"] = int(self.current["score"])
            self.items.append(self.current)
            self.current = None

parser = RankingParser()
parser.feed(HTML)
for item in parser.items:
    print(f"#{item['rank']} {item['title']} ({item['score']})")

